import hashlib
import random
import string
from typing import List, Tuple, Dict

class RainbowTable:
    def __init__(self, hash_func='md5', chain_length=1000, num_chains=10000):
        self.hash_func = hash_func
        self.chain_length = chain_length
        self.num_chains = num_chains
        self.tables: Dict[int, List[Tuple[str, str]]] = {}
        self.password_chars = string.ascii_letters + string.digits
        self.password_length = 6

    def hash_password(self, password: str) -> str:
        """Hash a password using specified algorithm"""
        if self.hash_func == 'md5':
            return hashlib.md5(password.encode()).hexdigest()
        elif self.hash_func == 'sha1':
            return hashlib.sha1(password.encode()).hexdigest()
        else:
            raise ValueError(f"Unsupported hash function: {self.hash_func}")

    def reduce(self, hash_value: str, chain_index: int) -> str:
        """Convert hash back to password candidate"""
        # Simple reduction: take hash chars and map to password chars
        password = []
        for i, char in enumerate(hash_value[:self.password_length]):
            idx = (ord(char) + chain_index) % len(self.password_chars)
            password.append(self.password_chars[idx])
        return ''.join(password)

    def generate_chain(self, start_password: str) -> Tuple[str, str]:
        """Generate a chain from start to end"""
        current = start_password
        for i in range(self.chain_length):
            current = self.hash_password(current)
            if i < self.chain_length - 1:
                current = self.reduce(current, i)
        return start_password, current

    def build_table(self):
        """Build the rainbow table"""
        print(f"Building rainbow table with {self.num_chains} chains...")
        for chain_idx in range(self.num_chains):
            start = ''.join(random.choice(self.password_chars) 
                           for _ in range(self.password_length))
            start_pw, end_hash = self.generate_chain(start)

            if chain_idx not in self.tables:
                self.tables[chain_idx] = []
            self.tables[chain_idx].append((start_pw, end_hash))

        print(f"Table built: {sum(len(v) for v in self.tables.values())} chains stored")

    def crack_hash(self, target_hash: str) -> str:
        """Attempt to crack a hash using the rainbow table"""
        for chain_idx in self.tables:
            current = target_hash
            for i in range(self.chain_length):
                if i < self.chain_length - 1:
                    current = self.reduce(current, i)

                # Check if current matches any chain end
                for start_pw, end_hash in self.tables[chain_idx]:
                    if end_hash == current:
                        # Verify by regenerating chain
                        candidate = start_pw
                        for j in range(self.chain_length):
                            candidate = self.hash_password(candidate)
                            if j < self.chain_length - 1:
                                candidate = self.reduce(candidate, j)

                        if candidate == target_hash:
                            # Find the actual password in the chain
                            for j in range(self.chain_length):
                                candidate = self.hash_password(candidate)
                                if candidate == target_hash:
                                    return self.reduce(target_hash, j)
                                if j < self.chain_length - 1:
                                    candidate = self.reduce(candidate, j)

        return None

# Example usage
